12	)
13	
14	// DEVDESK-309 (IS-05): the level 1 table sorts by Name, Registry and Stars
15	// through the shared datatable cycle (`.`).
16	
17	func sortRow(name, label, key string, stars int, hasStars bool) searchRow {
18		return searchRow{
19			img:   imagesearch.Image{Name: name, Repo: name, EntryKey: key, Stars: stars, HasStars: hasStars},
20			label: label,
21		}
22	}
23	
24	func sortNames(rows []searchRow) []string {
25		out := make([]string, len(rows))
26		for i, r := range rows {
27			out[i] = r.img.Name
28		}
29		return out
30	}
31	
32	func TestSearchSortColumnIndexes(t *testing.T) {
33		cols := searchColumns()
34		for idx, title := range map[int]string{searchColName: "Name", searchColRegistry: "Registry", searchColStars: "Stars"} {
35			if idx >= len(cols) || cols[idx].Title != title {
36				t.Errorf("column %d is not %q", idx, title)
37				continue
38			}
39			if cols[idx].Less == nil {
40				t.Errorf("column %q has no Less: it cannot be sorted by", title)
41			}
