1	package ociresources
2	
3	import (
4		"errors"
5		"log"
6		"net/url"
7		"strconv"
8		"strings"
9	
10		tea "charm.land/bubbletea/v2"
11		"charm.land/lipgloss/v2"
12	
13		"github.com/anthnel/devdesk/internal/imagesearch"
14		"github.com/anthnel/devdesk/internal/jobs"
15		"github.com/anthnel/devdesk/internal/oci"
16		"github.com/anthnel/devdesk/internal/ui/datatable"
17		"github.com/anthnel/devdesk/internal/ui/indicator"
18		"github.com/anthnel/devdesk/internal/ui/shortcut"
19		"github.com/anthnel/devdesk/internal/ui/theme"
20	)
21	
22	// searchRow is one line of the level 1 table: an image, and the label of the
23	// registry that returned it.
24	type searchRow struct {
25		img   imagesearch.Image
26		label string
27		// ref is the full reference (host/repo), what the footer describes.
28		ref string
29	}
30	
31	// searchRowReference returns the full reference of an image found in the
32	// registry at registryURL: the host, then the final repository path. Docker
33	// Hub is always written docker.io, whichever spelling it is configured under.
34	func searchRowReference(registryURL string, img imagesearch.Image) string {
35		host := oci.RegistryHost(registryURL)
36		if host == "" {
37			return img.Repo
38		}
39		if oci.IsDockerHub(registryURL) {
40			host = "docker.io"
41		}
42		return host + "/" + img.Repo
43	}
44	
45	// Column indexes of the level 1 table that can be sorted by (DEVDESK-309).
46	const (
47		searchColName     = 1
48		searchColRegistry = 2
49		searchColStars    = 3
50	)
51	
52	// searchColumns describes the level 1 table. Stars, Official and Description
53	// leave whole when the terminal narrows, in that reverse order (Description,
54	// Stars, Official), through Optional and DropFirst: drop() takes the rightmost
55	// DropFirst column first, then the rightmost Optional one.
56	func searchColumns() []datatable.Column[searchRow] {
57		return []datatable.Column[searchRow]{
58			datatable.IndicatorColumn(
59				func(searchRow) indicator.State { return indicator.Idle },
60				func(searchRow) string { return theme.IconDocker },
61				func(searchRow) lipgloss.Style { return theme.IconStyle(theme.IconRoleImage) },
62			),
63			{
64				Title: "Name", Sizing: datatable.SizingContent, MinWidth: 24, Flex: 1,
65				Cell:   func(r searchRow) string { return r.img.Name },
66				Search: func(r searchRow) string { return r.img.Name },
67				Less:   lessSearchName,
68			},
69			{
70				Title: "Registry", Sizing: datatable.SizingContent, MinWidth: 16,
71				Cell: func(r searchRow) string { return r.label },
72				Less: lessSearchRegistry,
73			},
74			{
75				Title: "Stars", Sizing: datatable.SizingFixed, Optional: true, DropFirst: true, MinWidth: 6,
76				Less: lessSearchStars, DescFirst: true,
77				Cell: func(r searchRow) string {
78					if !r.img.HasStars {
79						return ""
80					}
81					return strconv.Itoa(r.img.Stars)
82				},
83			},
84			{
85				Title: "Official", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 10,
86				Cell: func(r searchRow) string {
87					if r.img.Official {
88						return "official"
89					}
90					return ""
91				},
92			},
93			{
94				Title: "Description", Sizing: datatable.SizingContent, Optional: true, DropFirst: true,
95				MinWidth: 20, Flex: 2,
96				Cell:   func(r searchRow) string { return r.img.Description },
97				Search: func(r searchRow) string { return r.img.Description },
98			},
99		}
100	}
101	
102	// newSearchTable builds the level 1 table; rebuildSearchTable orders its rows.
103	func newSearchTable() *datatable.Model[searchRow] {
104		t := datatable.New(datatable.Config[searchRow]{
105			Columns:    searchColumns(),
106			SortColumn: -1,
107		})
108		return &t
109	}
110	
111	// rebuildSearchTable hands the collected images to the table.
112	func (b *RegistryBrowser) rebuildSearchTable() {
113		rows := make([]searchRow, len(b.images))
114		for i, img := range b.images {
115			label, ref := "", img.Repo
116			if e := b.entryFor(img.EntryKey); e != nil {
117				label = b.entryLabel(img.EntryKey)
118				ref = searchRowReference(e.URL, img)
119			}
120			rows[i] = searchRow{img: img, label: label, ref: ref}
121		}
122		sortSearchRows(b.searchQuery, rows)
123		// The cursor follows the selected row by (EntryKey, Repo), not by index:
124		// rows of another registry land before or after it. Nothing selected (an
125		// empty table, so also a new search) goes to the first row, because an
126		// empty table keeps its old cursor index; a vanished row stays put.
127		prev, hadSel := b.searchTable.Selected()
128		b.searchTable.SetItems(rows)
129		if !hadSel {
130			b.searchTable.GotoTop()
131		} else {
132			for i, r := range b.searchTable.Visible() {
133				if r.img.EntryKey == prev.img.EntryKey && r.img.Repo == prev.img.Repo {
134					b.searchTable.SetCursor(i)
135					break
136				}
137			}
138		}
139		b.resizeTables()
140	}
141	
142	// AddImageResults takes one registry's answer. It returns false, touching
143	// nothing, when the answer belongs to another lot. pendingSearches never goes
144	// below zero.
145	func (b *RegistryBrowser) AddImageResults(msg ImageSearchResultMsg) bool {
146		if msg.Gen != b.gen {
147			return false
148		}
149		if b.pendingSearches > 0 {
150			b.pendingSearches--
151		}
152		oc := imagesearch.Classify(msg.Err, len(msg.Images), msg.Partial)
153		if b.outcomes == nil {
154			b.outcomes = map[string]imagesearch.Outcome{}
155		}
156		b.outcomes[msg.EntryKey] = oc
157		if oc.Verdict == imagesearch.VerdictOK {
158			for _, img := range msg.Images {
159				img.EntryKey = msg.EntryKey
160				b.images = append(b.images, img)
161			}
162		}
163		b.rebuildSearchTable()
164		return true
165	}
166	
167	// handleImagesKeyMsg handles the keys of the level 1 table. left goes straight
168	// back to the form; esc acts in order: the filter bar while it is open, then a
169	// confirmed query, then it cancels the lot and goes back to the form (which
170	// keeps the typed name and the selection). The lot's late answers are no
171	// longer wanted and are dropped
172	// (TestEscAtLevelOneCancelsTheLotAndIgnoresItsLateAnswers). enter does
173	// nothing: a row has no action yet; → opens the row's tags.
174	func (b *RegistryBrowser) handleImagesKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
175		if b.searchTable.InEditMode() {
176			return b, b.searchTable.Update(msg)
177		}
178		switch msg.String() {
179		case "right":
180			return b.openSelectedImageTags()
181		case "esc":
182			if bar := b.searchTable.FilterBar(); bar.SearchQuery() != "" {
183				bar.ClearSearch()
184				b.searchTable.SetItems(b.searchTable.Items())
185				return b, nil
186			}
187			return b.backToForm()
188		case "left":
189			return b.backToForm()
190		case "enter":
191			return b, nil
192		}
193		return b, b.searchTable.Update(msg)
194	}
