196	// backToForm cancels the lot and returns to the form, which keeps the typed
197	// name and the selection. Late answers of the lot are dropped.
198	func (b *RegistryBrowser) backToForm() (*RegistryBrowser, tea.Cmd) {
199		b.abandonLot()
200		b.state = browserStateInput
201		b.searchTable.Blur()
202		b.updateFocus()
203		return b, nil
204	}
