206	// handleImageSearchResult records one registry's answer; a stale one is ignored.
207	func (m Model) handleImageSearchResult(msg ImageSearchResultMsg) (tea.Model, tea.Cmd) {
208		if m.registryBrowser == nil || !m.registryBrowser.AddImageResults(msg) {
209			return m, nil
210		}
211		oc, _ := m.registryBrowser.Outcome(msg.EntryKey)
212		alias := msg.EntryKey
213		if e := m.registryBrowser.entryFor(msg.EntryKey); e != nil {
214			alias = entryAlias(*e)
215		}
216		logSearchOutcome(alias, oc, msg.Err)
217		return m, nil
218	}
219	
220	// logSearchOutcome logs a registry's verdict: failed as an error, refused as
221	// info, nothing for ok or no result. The cause goes through searchErrorCause,
222	// so no secret or typed text reaches the log.
223	func logSearchOutcome(alias string, oc imagesearch.Outcome, err error) {
224		switch oc.Verdict {
225		case imagesearch.VerdictFailed:
226			log.Printf("ERROR [oci_resources] image search on %s: %s", alias, searchErrorCause(err))
227		case imagesearch.VerdictRefused:
228			log.Printf("INFO [oci_resources] image search on %s: unsupported or refused: %s", alias, searchErrorCause(err))
229		}
230	}

70	var defaultImageSearcher imagesearch.Searcher = imagesearch.ByRegistry(imagesearch.HubSearcher{}, imagesearch.CatalogSearcher{})
71	
72	// imageSearchDeadline bounds one registry's whole search.
73	var imageSearchDeadline = 15 * time.Second
74	
75	// targetFor describes entry for the Searcher, with the same alias, address and
76	// credentials (D12) the tag flow uses.
77	func (b *RegistryBrowser) targetFor(entry browserRegistryEntry) imagesearch.Target {
78		user, pass := b.credsFor(entry)
79		return imagesearch.Target{
80			EntryKey: entry.key, Alias: entryAlias(entry), RegistryURL: entry.URL,
81			APIURL: registryAPIURL(entry.URL), RepoPrefix: entry.repoPrefix,
82			Username: user, Password: pass,
83		}
84	}
