86	// startImageSearch opens a lot and asks the Searcher once per entry.
87	func (b *RegistryBrowser) startImageSearch(query string, entries []browserRegistryEntry) (*RegistryBrowser, tea.Cmd) {
88		ctx := b.beginRequests()
89		b.images = nil
90		b.outcomes = map[string]imagesearch.Outcome{}
91		b.searchQuery = query
92		b.searchGen = b.gen
93		b.searchKeys = make([]string, len(entries))
94		for i, entry := range entries {
95			b.searchKeys[i] = entry.key
96		}
97		b.searchTable.SetItems(nil)
98	
99		cmds := make([]tea.Cmd, 0, len(entries))
100		for _, entry := range entries {
101			b.pendingSearches++
102			cmds = append(cmds, searchImagesCmd(ctx, b.gen, b.targetFor(entry), imagesearch.Query{Text: query}, b.searcher, imageSearchDeadline))
103		}
104		b.state = browserStateImages
105		b.searchTable.Focus()
106		return b, tea.Batch(cmds...)
107	}
108	
109	// searchImagesCmd runs one registry's search under deadline (read from
110	// imageSearchDeadline by the caller, in Update), inside the lot's context. It
111	// reads no model state (Rule 110).
112	func searchImagesCmd(parent context.Context, gen uint64, t imagesearch.Target, q imagesearch.Query, s imagesearch.Searcher, deadline time.Duration) tea.Cmd {
113		return func() tea.Msg {
114			ctx, cancel := context.WithTimeout(parent, deadline)
115			defer cancel()
116			images, partial, err := s.Search(ctx, t, q)
117			return ImageSearchResultMsg{Gen: gen, EntryKey: t.EntryKey, Images: images, Partial: partial, Err: err}
118		}
119	}
