121	// RegistryBrowserOutcomes returns a copy of the verdicts of the open browser's
122	// current search, nil when the browser is closed. For tests and IS-13.
123	func (m Model) RegistryBrowserOutcomes() map[string]imagesearch.Outcome {
124		if m.registryBrowser == nil {
125			return nil
126		}
127		return maps.Clone(m.registryBrowser.outcomes)
128	}
