	b, keyA, _ := cursorBrowser(t)
	arriveStars(t, b, keyA, map[string]int{"alpha": 5, "bravo": 50})
	b.handleImagesKeyMsg(testutil.Key("/"))
	for _, msg := range testutil.Type("bra") {
